28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form (a '+' followed by 8 to 15 digits)")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
60	    private Set<Pet> pets;
61	
62	    public String getAddress() {
63	        return this.address;
64	    }
65	
66	    public void setAddress(String address) {
67	        this.address = address;
68	    }
69	
70	    public String getCity() {
71	        return this.city;
72	    }
73	
74	    public void setCity(String city) {
75	        this.city = city;
76	    }
77	
78	    public String getTelephone() {
79	        return this.telephone;
80	    }
81	
82	    public void setTelephone(String telephone) {
83	        this.telephone = telephone;
84	    }
85	
86	    public String getEmail() {
87	        return this.email;
88	    }
89	
90	    public void setEmail(String email) {
91	        this.email = normalizeEmail(email);
92	    }
93	
94	    public LocalDate getRegistrationDate() {
95	        return this.registrationDate;
96	    }
97	
98	    public void setRegistrationDate(LocalDate registrationDate) {
99	        this.registrationDate = registrationDate;
100	    }
101	
102	    /**
103	     * Normalize an email to its canonical stored form, which is lower-cased. This is the single
104	     * source of truth for how an email is persisted, so inputs that differ only in letter case
105	     * are stored identically. Applied by {@link #setEmail(String)} so every persistence path
106	     * (create and update, mapper or hand-copied) stores the same canonical value.
107	     *
108	     * @param email the raw email, possibly {@code null}
109	     * @return the lower-cased form, or {@code null} if the input was {@code null}
110	     */
111	    public static String normalizeEmail(String email) {
112	        return email == null ? null : email.toLowerCase();
113	    }
114	
115	    /**
116	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
117	     * truth for how a telephone is compared and persisted, so inputs that differ only in
118	     * formatting (spaces, dashes, brackets) are treated as the same number.
119	     *
120	     * <p>The rules are:
121	     * <ul>
122	     *   <li>spaces, dashes and brackets are stripped;</li>
123	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
124	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
125	     *       is dropped from the national digits;</li>
126	     *   <li>the result must have 8 to 15 digits after the {@code '+'}.</li>
127	     * </ul>
128	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
129	     * values are returned unchanged.
130	     *
131	     * @param telephone the raw telephone, possibly {@code null}
132	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
133	     *     valid E.164 number
134	     */
135	    public static String normalizeTelephone(String telephone) {
136	        if (telephone == null) {
137	            return null;
138	        }
139	        String trimmed = telephone.trim();
140	        boolean hasCountryCode = trimmed.startsWith("+");
141	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
142	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
143	        if (hasCountryCode) {
144	            stripped = stripped.substring(1);
145	        }
146	        if (!stripped.matches("\\d+")) {
147	            return null;
148	        }
149	        String digits;
150	        if (hasCountryCode) {
151	            digits = stripped;
152	        } else {
153	            if (stripped.startsWith("0")) {
154	                stripped = stripped.substring(1);
155	            }
156	            digits = "61" + stripped;
157	        }
158	        if (digits.length() < 8 || digits.length() > 15) {
159	            return null;
160	        }
161	        return "+" + digits;
162	    }
163	
164	    protected Set<Pet> getPetsInternal() {
165	        if (this.pets == null) {
166	            this.pets = new HashSet<>();
167	        }
168	        return this.pets;
169	    }
170	
171	    protected void setPetsInternal(Set<Pet> pets) {
172	        this.pets = pets;
173	    }
174	
175	    public List<Pet> getPets() {
176	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
177	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
178	        return Collections.unmodifiableList(sortedPets);
179	    }
180	
181	    public void setPets(List<Pet> pets) {
182	        this.pets = new HashSet<>(pets);
183	    }
184	
185	    public void addPet(Pet pet) {
186	        getPetsInternal().add(pet);
187	        pet.setOwner(this);
188	    }
189	
190	    /**
191	     * Return the Pet with the given name, or null if none found for this Owner.
192	     *
193	     * @param name to test
194	     * @return true if pet name is already in use
195	     */
196	    public Pet getPet(String name) {
197	        return getPet(name, false);
198	    }
199	
200	    /**
201	     * Return the Pet with the given name, or null if none found for this Owner.
202	     *
203	     * @param name to test
204	     * @return true if pet name is already in use
205	     */
206	    public Pet getPet(String name, boolean ignoreNew) {
207	        name = name.toLowerCase();
208	        for (Pet pet : getPetsInternal()) {
209	            if (!ignoreNew || !pet.isNew()) {
210	                String compName = pet.getName();
211	                compName = compName.toLowerCase();
212	                if (compName.equals(name)) {
213	                    return pet;
214	                }
215	            }
216	        }
217	        return null;
218	    }
219	
220	    public Pet getPet(Integer petId) {
221	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
222	    }
223	
224	    @Override
225	    public String toString() {
226	        return new ToStringCreator(this)
227	
228	            .append("id", this.getId())
229	            .append("new", this.isNew())
230	            .append("lastName", this.getLastName())
231	            .append("firstName", this.getFirstName())
232	            .append("address", this.address)
233	            .append("city", this.city)
234	            .append("telephone", this.telephone)
235	            .toString();
236	    }
237	}
